import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null || s.isEmpty()) {
            return;
        }
        int n = s.length();
        boolean[][] isPal = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s.charAt(i) == s.charAt(j) && (j - i < 2 || isPal[i + 1][j - 1])) {
                    isPal[i][j] = true;
                }
            }
        }
        List<String> path = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        dfs(s, 0, isPal, path, sb);
    }

    private static void dfs(String s, int start, boolean[][] isPal, List<String> path, StringBuilder sb) {
        int n = s.length();
        if (start == n) {
            for (int i = 0; i < path.size(); i++) {
                if (i > 0) sb.append(' ');
                sb.append(path.get(i));
            }
            sb.append('\n');
            System.out.print(sb.toString());
            sb.setLength(sb.length() - (path.size() == 0 ? 1 : path.size() * 2 - 1));
            return;
        }
        for (int end = start; end < n; end++) {
            if (isPal[start][end]) {
                String part = s.substring(start, end + 1);
                path.add(part);
                dfs(s, end + 1, isPal, path, sb);
                path.remove(path.size() - 1);
            }
        }
    }
}
